import * as React from "react";
import { cx } from "./cx";

export interface SpinnerProps extends React.HTMLAttributes<HTMLSpanElement> {
  label?: string;
}

/** Hairline ring. Stops under prefers-reduced-motion. */
export function Spinner({ label = "Loading", className, ...props }: SpinnerProps) {
  return (
    <span role="status" aria-label={label} className={cx("rs-spinner", className)} {...props}>
      <svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true">
        <circle
          cx="8"
          cy="8"
          r="6.5"
          stroke="currentColor"
          strokeWidth="1"
          strokeLinecap="butt"
          strokeLinejoin="miter"
          vectorEffect="non-scaling-stroke"
          strokeDasharray="28 13"
        />
      </svg>
    </span>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Spinner: 1px currentColor hairline ring. Raster icon law. ── */
.rs-spinner{display:inline-flex;width:16px;height:16px;color:var(--text);vertical-align:middle}
.rs-spinner svg{display:block;width:16px;height:16px;animation:rs-spin .7s linear infinite}
@keyframes rs-spin{to{transform:rotate(360deg)}}
